// 根据单词与释义生成一句包含该词的例句。
// 优先用内置精选例句；未覆盖时按词义/词性匹配模板，避免生硬硬套。
function getExample(word, meaning) {
  if (!word) return { en: "", cn: "" };
  const w = String(word).trim();
  const low = w.toLowerCase();
  const key = Object.keys(EXAMPLES).find(k => k.toLowerCase() === low);
  if (key) return EXAMPLES[key];

  // 不再根据释义自动套用模板生成例句——机器硬造的例句（如 "She felt occur..."）
  // 经常出现语法或语义错误。只展示 EXAMPLES 中真实收录的例句，没有则留空，
  // 由调用处判断为"暂无例句"而不展示。
  return { en: "", cn: "" };
}
